<script lang="ts">
 import CardFace from '$lib/cards/CardFace.svelte';
 import CardSymbol from '$lib/cards/CardSymbol.svelte';
 import {canonicalCard} from '../cards/catalog';
 import type {PublicSetup,PlayerState} from './setup';
 let {game,player,inspect}:{game:PublicSetup;player:PlayerState;inspect:(id:string)=>void}=$props();
 let index=$state(0);
 const colonies=$derived(game.discovery?.colonies?.filter(c=>c.owner===player.position)??[]);
 const colony=$derived(colonies[Math.min(index,colonies.length-1)]);
</script>
<section class="colony-register" aria-label={`${player.name} public colonies`}>
 {#if colony}<nav aria-label="Colony register"><button aria-label="Previous colony" disabled={colonies.length<2} onclick={()=>index=(index+colonies.length-1)%colonies.length}>‹</button><span>{canonicalCard(colony.card).title}<small>Colony {Math.min(index+1,colonies.length)} / {colonies.length} · permanent territory</small></span><button aria-label="Next colony" disabled={colonies.length<2} onclick={()=>index=(index+1)%colonies.length}>›</button></nav>
  <p class="register-cue">Inspect the full System freely · scroll for every colony detail ↕</p><div class="colony-object"><button class="face" aria-label={`Read full colony ${canonicalCard(colony.card).title}`} onclick={()=>inspect(colony.card)}><CardFace card={canonicalCard(colony.card)}/></button><div class="register-facts"><h3>{canonicalCard(colony.card).title}</h3><p>{player.name}’s permanent territory. It is no longer an Exploration location.</p><div class="disc-stack" aria-label="Actual colony production discs">{#each colony.discs as disc,i}<span class:placeholder={disc.placeholder}><i aria-hidden="true"><CardSymbol kind={disc.placeholder?'star':disc.track}/></i><b>{disc.track==='food'?'Food':'Ore'}</b><small>{disc.placeholder?'Permanent placeholder':i===0?'Retained outpost disc':'Additional colony disc'}</small></span>{/each}</div><p>{colony.settledPower} settling power · {colony.discs.length} disc{colony.discs.length===1?'':'s'}. Colony discs improve production without increasing automation.</p>{#if colony.solar}<p>Erratic Solar Activity stays with this colony: +1 VP.</p>{/if}<p>Printed benefit: {canonicalCard(colony.card).sections.find(s=>s.label==='Colonize')?.text}</p></div></div>
 {:else}<p>No established colonies. Outposts remain on the Exploration board until a legal colonization Action is completed.</p>{/if}
</section>
